<template>
  <main class="admin-page">
    <header class="admin-hero"><div><span class="eyebrow">STOCKWELL ADMIN</span><h1>Company control centre</h1><p>Live overview of StockWell operations.</p></div><router-link class="suggestions-link" to="/admin/suggestions">Review suggestions</router-link></header>
    <div v-if="loading" class="notice">Loading company data…</div>
    <div v-if="message" class="notice">{{ message }}</div>
    <div v-if="loadErrors.length" class="notice warning">Some sections could not be loaded: {{ loadErrors.join(', ') }}</div>

    <section class="stats-grid">
      <article v-for="card in statCards" :key="card.label" class="stat-card"><span>{{ card.label }}</span><strong>{{ card.value }}</strong></article>
    </section>

    <section class="quick-grid">
      <article class="quick-card"><span>ACTIVE ORDERS</span><strong>{{ stats.active_orders ?? 0 }}</strong><small>Pending, confirmed or processing</small></article>
      <article class="quick-card"><span>ACTIVE DELIVERIES</span><strong>{{ stats.active_deliveries ?? 0 }}</strong><small>Pending or in transit</small></article>
      <article class="quick-card"><span>ADMINS</span><strong>{{ stats.admins ?? 0 }}</strong><small>Company administrator accounts</small></article>
      <article class="quick-card"><span>SUPPLIERS</span><strong>{{ stats.suppliers ?? 0 }}</strong><small>Distinct suppliers</small></article>
    </section>

    <section class="panel"><div class="panel-heading"><div><span class="eyebrow">CATALOGUE</span><h2>Products & inventory</h2></div><button @click="showProductForm=!showProductForm">{{ showProductForm ? 'Close' : '+ Add product' }}</button></div>
      <form v-if="showProductForm" class="form-grid" @submit.prevent="addProduct"><input v-model="newProduct.product_name" required placeholder="Product name"/><input v-model="newProduct.category" placeholder="Category"/><input v-model.number="newProduct.quantity_available" type="number" min="0" placeholder="Stock"/><input v-model="newProduct.image_url" placeholder="Image URL"/><textarea v-model="newProduct.description" placeholder="Description"></textarea><button type="submit">Create product</button></form>
      <input class="search" v-model="productSearch" placeholder="Search products…"/>
      <div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Stock</th><th>Actions</th></tr></thead><tbody><tr v-for="p in filteredProducts" :key="p.product_id"><td><input v-model="p.product_name"/></td><td><input v-model="p.category"/></td><td><input v-model.number="p.quantity_available" type="number" min="0"/></td><td class="actions"><button @click="saveProduct(p)">Save</button><button class="danger" @click="removeProduct(p)">Delete</button></td></tr><tr v-if="!filteredProducts.length"><td colspan="4" class="empty">No products loaded.</td></tr></tbody></table></div>
    </section>

    <section class="panel"><div class="panel-heading"><div><span class="eyebrow">SUPPLIERS</span><h2>Supplier prices</h2></div></div>
      <form class="form-grid supplier-form" @submit.prevent="addSupplier"><select v-model.number="newSupplier.product_id" required><option :value="null" disabled>Select product</option><option v-for="p in products" :key="p.product_id" :value="p.product_id">{{ p.product_name }}</option></select><input v-model="newSupplier.supplier_name" required placeholder="Supplier"/><input v-model.number="newSupplier.price" required type="number" min="0" step="0.01" placeholder="Price"/><input v-model.number="newSupplier.minimum_quantity" type="number" min="1" placeholder="Min qty"/><button>Add price</button></form>
      <div class="table-wrap"><table><thead><tr><th>Product</th><th>Supplier</th><th>Price</th><th>Min qty</th><th>Actions</th></tr></thead><tbody><tr v-for="item in supplierPrices" :key="item.supplier_price_id"><td>{{ item.product_name }}</td><td><input v-model="item.supplier_name"/></td><td><input v-model.number="item.price" type="number" step="0.01"/></td><td><input v-model.number="item.minimum_quantity" type="number" min="1"/></td><td class="actions"><button @click="saveSupplier(item)">Save</button><button class="danger" @click="removeSupplier(item)">Delete</button></td></tr><tr v-if="!supplierPrices.length"><td colspan="5" class="empty">No supplier prices loaded.</td></tr></tbody></table></div>
    </section>

    <section class="two-col"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">STOKVELS</span><h2>All groups</h2></div></div><div class="list"><article v-for="g in stokvels" :key="g.stokvel_id"><strong>{{ g.stokvel_name }}</strong><span>{{ g.member_count }} members · Chairperson: {{ g.chairperson_name || '—' }}</span></article><p v-if="!stokvels.length" class="empty">No Stokvel data loaded.</p></div></section>
      <section class="panel"><div class="panel-heading"><div><span class="eyebrow">USERS</span><h2>All users</h2></div></div><div class="list"><article v-for="u in users" :key="u.user_id"><strong>{{ u.full_name }}</strong><span>{{ u.email }} · {{ u.role }}{{ u.stokvels ? ' · '+u.stokvels : '' }}</span></article><p v-if="!users.length" class="empty">No user data loaded.</p></div></section></section>

    <section class="panel"><div class="panel-heading"><div><span class="eyebrow">ORDERS</span><h2>Company-wide orders</h2></div></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Stokvel</th><th>Total</th><th>Status</th><th>Delivery</th></tr></thead><tbody><tr v-for="o in orders" :key="o.order_id"><td>#{{ o.order_id }}</td><td>{{ o.customer_name || '—' }}</td><td>{{ o.stokvel_name || '—' }}</td><td>R {{ money(o.total_amount) }}</td><td><select :value="o.order_status" @change="setOrderStatus(o,$event.target.value)"><option v-for="s in orderStatuses" :key="s">{{ s }}</option></select></td><td>{{ o.delivery_status || '—' }}</td></tr><tr v-if="!orders.length"><td colspan="6" class="empty">No orders loaded.</td></tr></tbody></table></div></section>

    <section class="panel"><div class="panel-heading"><div><span class="eyebrow">DELIVERIES</span><h2>Delivery operations</h2></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Address</th><th>Driver</th><th>Status</th><th>Date</th></tr></thead><tbody><tr v-for="d in deliveries" :key="d.delivery_id"><td>#{{ d.delivery_id }}</td><td>{{ d.delivery_address || '—' }}</td><td>{{ d.driver_name || '—' }}</td><td><select :value="d.delivery_status" @change="setDeliveryStatus(d,$event.target.value)"><option v-for="s in deliveryStatuses" :key="s">{{ s }}</option></select></td><td>{{ formatDate(d.delivery_date) }}</td></tr><tr v-if="!deliveries.length"><td colspan="5" class="empty">No deliveries loaded.</td></tr></tbody></table></div></section>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { getAdminDashboard,getAdminUsers,getAdminStokvels,getAdminProducts,createAdminProduct,updateAdminProduct,deleteAdminProduct,getAdminSupplierPrices,createAdminSupplierPrice,updateAdminSupplierPrice,deleteAdminSupplierPrice,getAdminOrders,updateAdminOrderStatus,getAdminDeliveries,updateAdminDelivery } from '../services/api.js';
const router=useRouter(); const loading=ref(false); const message=ref(''); const loadErrors=ref([]); const stats=ref({}); const users=ref([]); const stokvels=ref([]); const products=ref([]); const supplierPrices=ref([]); const orders=ref([]); const deliveries=ref([]); const productSearch=ref(''); const showProductForm=ref(false);
const newProduct=ref({product_name:'',description:'',category:'Staples',image_url:'',quantity_available:0}); const newSupplier=ref({product_id:null,supplier_name:'',price:0,minimum_quantity:10});
const orderStatuses=['Pending','Confirmed','Processing','Completed','Cancelled']; const deliveryStatuses=['Pending','In Transit','Delivered','Cancelled'];
const statCards=computed(()=>[{label:'Users',value:stats.value.users??0},{label:'Stokvels',value:stats.value.stokvels??0},{label:'Products',value:stats.value.products??0},{label:'Orders',value:stats.value.orders??0},{label:'Low stock',value:stats.value.low_stock??0},{label:'Revenue',value:`R ${money(stats.value.revenue)}`}]);
const filteredProducts=computed(()=>{const q=productSearch.value.toLowerCase().trim();return products.value.filter(p=>!q||`${p.product_name} ${p.category||''}`.toLowerCase().includes(q));});
const notify=t=>{message.value=t;setTimeout(()=>{if(message.value===t)message.value='';},3500)}; const money=v=>Number(v||0).toFixed(2); const formatDate=v=>v?new Date(v).toLocaleDateString():'—';
async function safe(label,fn){try{return await fn()}catch(e){if(e.response?.status===401||e.response?.status===403){router.replace('/login-signup');return null}loadErrors.value.push(label);return null}}
async function load(){loading.value=true;loadErrors.value=[];const [d,u,s,p,sp,o,del]=await Promise.all([safe('dashboard',getAdminDashboard),safe('users',getAdminUsers),safe('Stokvels',getAdminStokvels),safe('products',getAdminProducts),safe('supplier prices',getAdminSupplierPrices),safe('orders',getAdminOrders),safe('deliveries',getAdminDeliveries)]);if(d)stats.value=d.stats||{};if(u)users.value=u.users||[];if(s)stokvels.value=s.stokvels||[];if(p){products.value=p.products||[];if(!newSupplier.value.product_id&&products.value[0])newSupplier.value.product_id=products.value[0].product_id}if(sp)supplierPrices.value=sp.supplierPrices||[];if(o)orders.value=o.orders||[];if(del)deliveries.value=del.deliveries||[];loading.value=false}
async function addProduct(){try{const r=await createAdminProduct(newProduct.value);products.value.unshift(r.product);newProduct.value={product_name:'',description:'',category:'Staples',image_url:'',quantity_available:0};showProductForm.value=false;notify('Product created.')}catch(e){notify(e.response?.data?.message||'Unable to create product.')}}
async function saveProduct(p){try{const r=await updateAdminProduct(p.product_id,p);Object.assign(p,r.product);notify('Product saved.')}catch(e){notify(e.response?.data?.message||'Unable to save product.')}}
async function removeProduct(p){if(!confirm(`Delete ${p.product_name}?`))return;try{await deleteAdminProduct(p.product_id);products.value=products.value.filter(x=>x.product_id!==p.product_id);notify('Product deleted.')}catch(e){notify(e.response?.data?.message||'Unable to delete product.')}}
async function addSupplier(){try{const r=await createAdminSupplierPrice(newSupplier.value);supplierPrices.value.unshift(r.supplierPrice);newSupplier.value={product_id:products.value[0]?.product_id||null,supplier_name:'',price:0,minimum_quantity:10};notify('Supplier price added.')}catch(e){notify(e.response?.data?.message||'Unable to add supplier price.')}}
async function saveSupplier(i){try{const r=await updateAdminSupplierPrice(i.supplier_price_id,i);Object.assign(i,r.supplierPrice);notify('Supplier price saved.')}catch(e){notify(e.response?.data?.message||'Unable to save supplier price.')}}
async function removeSupplier(i){if(!confirm('Delete this supplier price?'))return;try{await deleteAdminSupplierPrice(i.supplier_price_id);supplierPrices.value=supplierPrices.value.filter(x=>x.supplier_price_id!==i.supplier_price_id);notify('Supplier price deleted.')}catch(e){notify(e.response?.data?.message||'Unable to delete supplier price.')}}
async function setOrderStatus(o,status){try{await updateAdminOrderStatus(o.order_id,status);o.order_status=status;notify(`Order #${o.order_id} updated.`)}catch(e){notify(e.response?.data?.message||'Unable to update order.')}}
async function setDeliveryStatus(d,status){try{await updateAdminDelivery(d.delivery_id,{delivery_status:status});d.delivery_status=status;notify(`Delivery #${d.delivery_id} updated.`)}catch(e){notify(e.response?.data?.message||'Unable to update delivery.')}}
onMounted(load);
</script>

<style scoped>
.admin-page{min-height:100vh;padding:38px clamp(16px,4vw,64px);background:var(--sw-page-background);color:var(--sw-page-text);transition:background .25s,color .25s}.admin-hero{max-width:1400px;margin:0 auto 28px;display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.eyebrow{font-size:.68rem;letter-spacing:.16em;font-weight:800;opacity:.62}.admin-hero h1{font-size:clamp(2rem,4vw,3.4rem);margin:8px 0}.admin-hero p{margin:0;color:var(--sw-page-text-soft)}.suggestions-link,.panel button{padding:10px 15px;border-radius:11px;border:1px solid var(--sw-input-border);background:var(--sw-page-surface);color:var(--sw-page-text);text-decoration:none;cursor:pointer}.panel button,.form-grid button,.actions button{background:var(--sw-purple-900);color:#fff;border-color:var(--sw-purple-900)}.notice{max-width:1400px;margin:0 auto 16px;padding:12px 15px;border:1px solid var(--sw-input-border);border-radius:12px;background:var(--sw-page-surface)}.notice.warning{border-color:var(--sw-orange-600)}.stats-grid{max-width:1400px;margin:0 auto 18px;display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.stat-card,.quick-card,.panel{border:1px solid var(--sw-input-border);background:var(--sw-page-surface);box-shadow:0 12px 30px rgba(0,0,0,.08)}.stat-card{padding:18px;border-radius:16px}.stat-card span,.quick-card span{font-size:.65rem;font-weight:800;letter-spacing:.1em;opacity:.62}.stat-card strong,.quick-card strong{display:block;font-size:1.55rem;margin-top:7px}.quick-grid{max-width:1400px;margin:0 auto 24px;display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.quick-card{padding:16px;border-radius:16px}.quick-card small{display:block;margin-top:5px;color:var(--sw-page-text-muted);font-size:.7rem}.panel{max-width:1400px;margin:0 auto 22px;padding:22px;border-radius:20px}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:16px}.panel-heading h2{margin:5px 0 0}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:15px}.supplier-form{grid-template-columns:2fr 1.5fr 1fr 1fr auto}.form-grid input,.form-grid textarea,.form-grid select,.search,td input,td select{width:100%;box-sizing:border-box;border:1px solid var(--sw-input-border);border-radius:9px;padding:10px;background:var(--sw-input-background);color:var(--sw-input-text)}.form-grid textarea{grid-column:1/-1;min-height:75px}.search{display:block;margin-bottom:13px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--sw-input-border)}th{font-size:.65rem;letter-spacing:.08em;text-transform:uppercase;opacity:.6}.actions{display:flex;gap:6px}.actions .danger{background:var(--sw-red-600);border-color:var(--sw-red-600)}.two-col{max-width:1400px;margin:0 auto 22px;display:grid;grid-template-columns:1fr 1fr;gap:22px}.two-col .panel{margin:0}.list{display:grid;gap:9px}.list article{padding:13px;border-radius:12px;background:var(--sw-input-background)}.list strong,.list span{display:block}.list span{margin-top:4px;font-size:.76rem;color:var(--sw-page-text-muted)}.empty{text-align:center;opacity:.58;padding:18px}@media(max-width:1050px){.stats-grid{grid-template-columns:repeat(3,1fr)}.quick-grid{grid-template-columns:repeat(2,1fr)}.form-grid,.supplier-form{grid-template-columns:1fr 1fr}.two-col{grid-template-columns:1fr}}@media(max-width:600px){.admin-hero{display:block}.suggestions-link{display:inline-block;margin-top:15px}.stats-grid,.quick-grid{grid-template-columns:1fr 1fr}.form-grid,.supplier-form{grid-template-columns:1fr}.admin-page{padding:25px 14px}}
</style>